<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($title) ?> — IFMAP</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/public/assets/css/app.css"><link rel="stylesheet" href="/public/assets/css/auth.css"><link rel="stylesheet" href="/public/assets/css/customer-auth.css"></head><body class="auth-body customer-auth-body"><?= $content ?><script>document.querySelectorAll('[data-password]').forEach(function(button){button.addEventListener('click',function(){const input=this.previousElementSibling;input.type=input.type==='password'?'text':'password';this.textContent=input.type==='password'?'Afficher':'Masquer'})})</script></body></html>
